	/** The boom's angle up from level, radians: 32 degrees. */
	public static final float BOOM_ANGLE = (float) Math.toRadians(32);

	/** The shoes' lift off the ground through a step, metres: hung 0.5 m up while it digs, down on the ground while it moves. */
	public static float shoeLift(float walk) {
		return walk < 0.25F ? 0.5F * (1 - walk / 0.25F) : walk < 0.75F ? 0F : 0.5F * (walk - 0.75F) / 0.25F;
	}

	/** The shoes ahead of the tub through a step, metres: out 2 m and set down, then the tub moves up to them. */
	public static float shoeAhead(float walk) {
		return walk < 0.25F ? 2F * walk / 0.25F : walk < 0.75F ? 2F * (1 - (walk - 0.25F) / 0.5F) : 0F;
	}

	/** Set when the frame is drawn, from this machine's own state. */
	@Override
	public void setupAnim(PitVehicleRenderer.PitState state) {
		super.setupAnim(state);
		for (String wheel : WHEELS) {
			root().getChild(wheel).xRot = state.roll / WHEEL_RADIUS;   // turned through the distance rolled over the radius
		}
		ModelPart house = root().getChild(HOUSE);
		house.yRot = (float) Math.toRadians(state.swing);   // plus swings its front to its right
		house.getChild(BOOM).xRot = -BOOM_ANGLE;   // the boom stands at 32 degrees
		ModelPart shoes = house.getChild(SHOES);
		shoes.y -= shoeLift(state.walk) * 16F;
		shoes.z -= shoeAhead(state.walk) * 16F;
		ModelPart bucket = house.getChild(BUCKET);
		bucket.y = -state.bucketUp * 16F;
		bucket.z = -state.bucketOut * 16F;
		bucket.getChild("bucket_load").visible = state.loaded;
	}
